     * @param int $numElems
     * @return void
     */
    public static function startCANONICAL_JSON_SIGNATUREVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(1, $numElems, 1);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endGEL(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // GEL_ID
        $builder->required($o, 22);  // ENU_COVARIANCE_M2
        $builder->required($o, 44);  // OBSERVATION_REFS
        $builder->required($o, 46);  // CONVERGENCE_DIAGNOSTICS
        $builder->required($o, 48);  // PROVENANCE
        $builder->required($o, 52);  // PRODUCER_ID
        $builder->required($o, 54);  // SIGNATURE
        $builder->required($o, 56);  // CANONICAL_JSON_SIGNATURE
        return $o;
    }

    public static function finishGELBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$GEL");
    }
}
